-- =====================================================================
-- SIGAF · RECARGA de SUBROGADOS desde la cedula (hoja ss)
-- Reemplaza SOLO las facturas MIGRADAS (created_by IS NULL) por las 253
-- de la cedula; CONSERVA intactas las capturadas en la app por los usuarios.
-- Transaccional. Contrato por numero_interno (PERNOCTA = marco). Folios HGZ2-SS-HIST-*.
-- Estatus: PAGADO/PASIVO->pagada, TP->OOAD, AC->autorizada serv, SE/SERV->en servicio, DEV->devuelta.
-- =====================================================================

begin;

create temp table stg_ss (folio text, importe numeric(14,2), contrato text, mes int, anio int, mes_ej int, anio_ej int, gen text, fir text, ped text, cr text, pasivo boolean) on commit drop;


do $$ declare n int; begin
  select count(distinct contrato) into n from stg_ss s where not exists (select 1 from contratos c where c.numero_interno=s.contrato); if n>0 then raise exception 'Hay % contratos de la cedula que no existen en SIGAF (incluye PERNOCTA si no se dio de alta)', n; end if;
end $$;

-- Solo migradas (created_by null); conserva capturas en vivo
update facturas set sustituida_por_id=null where sustituida_por_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Capitulo De Subrogados' and f.created_by is null);
update facturas set sustituye_a_id=null where sustituye_a_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Capitulo De Subrogados' and f.created_by is null);
do $$ begin if to_regclass('ooad_import_filas') is not null then update ooad_import_filas set matched_factura_id=null where matched_factura_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Capitulo De Subrogados' and f.created_by is null); end if; end $$;
delete from facturas f using capitulos c where f.capitulo_id=c.id and c.nombre='Capitulo De Subrogados' and f.created_by is null;

with base as (
  select s.*, row_number() over (order by s.contrato, s.anio, s.mes, s.folio) rn,
         ct.id contrato_id, ct.partida_id, ct.proveedor_id, pa.capitulo_id
  from stg_ss s
  join contratos ct on ct.numero_interno = s.contrato
  join partidas pa on pa.id = ct.partida_id
  where not exists (select 1 from facturas f2 join capitulos c2 on c2.id=f2.capitulo_id where c2.nombre='Capitulo De Subrogados' and f2.folio_proveedor = s.folio)
)
select 'HGZ2-SS-HIST-'||lpad(rn::text,6,'0'), folio, capitulo_id, partida_id, contrato_id, proveedor_id,
       make_date(anio,mes,1), (make_date(anio,mes,1) + interval '1 month - 1 day')::date, mes_ej, anio_ej, 0.16, importe,
       gen::estatus_general, fir::estatus_firmas, ped::estatus_pedido_recepcion, cr, pasivo
from base;

select c.nombre, count(*) filter (where f.created_by is null) de_cedula, count(*) filter (where f.created_by is not null) en_vivo, count(*) total, to_char(sum(f.importe_factura),'FM999,999,999.00') importe from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Capitulo De Subrogados' group by c.nombre;

commit;
